Approach: Use an unordered_map to find the complement before storing the current value.
Time: O(n), Space: O(n)

C++ solution:
vector<int> twoSum(vector<int>& a, int target) {
    unordered_map<int,int> seen;
    for (int i = 0; i < (int)a.size(); ++i) {
        int need = target - a[i];
        if (seen.count(need)) return {seen[need], i};
        seen[a[i]] = i;
    }
    return {};
}

Approach: Swap characters from both ends and move inward.
Time: O(n), Space: O(1)

C++ solution:
void reverseString(string& s) {
    int l = 0, r = (int)s.size() - 1;
    while (l < r) swap(s[l++], s[r--]);
}

Approach: Use two pointers and skip characters that are not alphanumeric.
Time: O(n), Space: O(1)

C++ solution:
bool isPalindrome(string s) {
    int l = 0, r = (int)s.size() - 1;
    while (l < r) {
        while (l < r && !isalnum((unsigned char)s[l])) ++l;
        while (l < r && !isalnum((unsigned char)s[r])) --r;
        if (tolower((unsigned char)s[l]) != tolower((unsigned char)s[r])) return false;
        ++l; --r;
    }
    return true;
}

Approach: Track the minimum price so far and the best profit.
Time: O(n), Space: O(1)

C++ solution:
int maxProfit(vector<int>& prices) {
    int mn = INT_MAX, best = 0;
    for (int p : prices) {
        mn = min(mn, p);
        best = max(best, p - mn);
    }
    return best;
}

Approach: Write nonzero values forward with a write pointer, then fill the remainder with zeros.
Time: O(n), Space: O(1)

C++ solution:
void moveZeroes(vector<int>& a) {
    int write = 0;
    for (int x : a) if (x != 0) a[write++] = x;
    while (write < (int)a.size()) a[write++] = 0;
}

Approach: Compare the middle element and discard half the search interval.
Time: O(log n), Space: O(1)

C++ solution:
int binarySearch(vector<int>& a, int target) {
    int l = 0, r = (int)a.size() - 1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (a[m] == target) return m;
        if (a[m] < target) l = m + 1;
        else r = m - 1;
    }
    return -1;
}

Approach: Use two pointers, append the smaller value, then append the remaining suffix.
Time: O(n+m), Space: O(n+m)

C++ solution:
vector<int> mergeSorted(vector<int>& a, vector<int>& b) {
    vector<int> out;
    int i = 0, j = 0;
    while (i < (int)a.size() && j < (int)b.size())
        out.push_back(a[i] < b[j] ? a[i++] : b[j++]);
    while (i < (int)a.size()) out.push_back(a[i++]);
    while (j < (int)b.size()) out.push_back(b[j++]);
    return out;
}

Approach: Count frequencies, then scan the string in original order.
Time: O(n), Space: O(1) for a fixed alphabet

C++ solution:
char firstUnique(string s) {
    vector<int> freq(256, 0);
    for (unsigned char c : s) ++freq[c];
    for (unsigned char c : s) if (freq[c] == 1) return c;
    return '#';
}

Approach: Sliding window plus last-seen positions moves the left boundary past duplicates.
Time: O(n), Space: O(1) for a fixed byte alphabet

C++ solution:
int lengthOfLongestSubstring(string s) {
    vector<int> last(256, -1);
    int left = 0, best = 0;
    for (int r = 0; r < (int)s.size(); ++r) {
        unsigned char c = s[r];
        left = max(left, last[c] + 1);
        last[c] = r;
        best = max(best, r - left + 1);
    }
    return best;
}

Approach: Sort each word to form a canonical key, then group by key. A 26-count signature also works.
Time: O(n * k log k), Space: O(n * k)

C++ solution:
vector<vector<string>> groupAnagrams(vector<string>& words) {
    unordered_map<string, vector<string>> groups;
    for (auto word : words) {
        string key = word;
        sort(key.begin(), key.end());
        groups[key].push_back(word);
    }
    vector<vector<string>> ans;
    for (auto& [key, group] : groups) ans.push_back(group);
    return ans;
}

Approach: Write prefix products into the output, then multiply by a running suffix product.
Time: O(n), Space: O(1) extra, excluding output

C++ solution:
vector<int> productExceptSelf(vector<int>& a) {
    int n = a.size();
    vector<int> out(n, 1);
    for (int i = 1; i < n; ++i) out[i] = out[i-1] * a[i-1];
    int suffix = 1;
    for (int i = n-1; i >= 0; --i) {
        out[i] *= suffix;
        suffix *= a[i];
    }
    return out;
}

Approach: Sort by start; merge with the last output interval when ranges overlap.
Time: O(n log n), Space: O(n)

C++ solution:
vector<vector<int>> mergeIntervals(vector<vector<int>>& a) {
    sort(a.begin(), a.end());
    vector<vector<int>> out;
    for (auto& x : a) {
        if (out.empty() || out.back()[1] < x[0]) out.push_back(x);
        else out.back()[1] = max(out.back()[1], x[1]);
    }
    return out;
}

Approach: Start at both ends; move the shorter line because width shrinks and the taller line cannot improve the current limiting height.
Time: O(n), Space: O(1)

C++ solution:
int maxArea(vector<int>& h) {
    int l = 0, r = (int)h.size() - 1, best = 0;
    while (l < r) {
        best = max(best, min(h[l], h[r]) * (r - l));
        if (h[l] < h[r]) ++l;
        else --r;
    }
    return best;
}

Approach: Dutch National Flag: low marks next zero, mid scans, high marks next two.
Time: O(n), Space: O(1)

C++ solution:
void sortColors(vector<int>& a) {
    int low = 0, mid = 0, high = (int)a.size() - 1;
    while (mid <= high) {
        if (a[mid] == 0) swap(a[low++], a[mid++]);
        else if (a[mid] == 1) ++mid;
        else swap(a[mid], a[high--]);
    }
}

Approach: Kadane's algorithm decides whether to extend the current subarray or start at the current value.
Time: O(n), Space: O(1)

C++ solution:
int maxSubArray(vector<int>& a) {
    int cur = a[0], best = a[0];
    for (int i = 1; i < (int)a.size(); ++i) {
        cur = max(a[i], cur + a[i]);
        best = max(best, cur);
    }
    return best;
}

Approach: Boyer-Moore voting cancels different pairs; the majority survives as the candidate.
Time: O(n), Space: O(1)

C++ solution:
int majorityElement(vector<int>& a) {
    int candidate = 0, count = 0;
    for (int x : a) {
        if (count == 0) candidate = x;
        count += (x == candidate) ? 1 : -1;
    }
    return candidate; // verify count if a majority is not guaranteed
}

Approach: Normalize k modulo n, reverse the whole array, then reverse the first k and the remaining n-k elements.
Time: O(n), Space: O(1)

C++ solution:
void rotate(vector<int>& a, int k) {
    int n = a.size();
    if (n == 0) return;
    k %= n;
    reverse(a.begin(), a.end());
    reverse(a.begin(), a.begin() + k);
    reverse(a.begin() + k, a.end());
}

Approach: Start with the first string and shorten the prefix until every string begins with it.
Time: O(total characters compared), Space: O(1) extra

C++ solution:
string longestCommonPrefix(vector<string>& s) {
    if (s.empty()) return "";
    string p = s[0];
    for (int i = 1; i < (int)s.size(); ++i) {
        while (s[i].compare(0, p.size(), p) != 0) p.pop_back();
        if (p.empty()) break;
    }
    return p;
}

Approach: Push opening brackets; each closing bracket must match the most recent opening bracket.
Time: O(n), Space: O(n)

C++ solution:
bool isValid(string s) {
    stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else {
            if (st.empty()) return false;
            char t = st.top(); st.pop();
            if ((c == ')' && t != '(') ||
                (c == ']' && t != '[') ||
                (c == '}' && t != '{')) return false;
        }
    }
    return st.empty();
}

Approach: Use the expected sum n(n+1)/2 minus the actual sum, or XOR to avoid sum overflow.
Time: O(n), Space: O(1)

C++ solution:
int missingNumber(vector<int>& a) {
    int n = a.size();
    long long expected = 1LL * n * (n + 1) / 2;
    for (int x : a) expected -= x;
    return (int)expected;
}

Approach: A write pointer records where the next new value belongs.
Time: O(n), Space: O(1)

C++ solution:
int removeDuplicates(vector<int>& a) {
    if (a.empty()) return 0;
    int write = 1;
    for (int read = 1; read < (int)a.size(); ++read)
        if (a[read] != a[write-1]) a[write++] = a[read];
    return write;
}
